create table public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
alter table public.admin_users enable row level security;
revoke all on public.admin_users from anon, authenticated;
grant select on public.admin_users to authenticated;
create policy admin_read_own on public.admin_users for select to authenticated using (user_id = (select auth.uid()));
create function public.is_admin() returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.admin_users where user_id = (select auth.uid())); $$;
revoke all on function public.is_admin() from public, anon;
grant execute on function public.is_admin() to authenticated;
grant insert, update, delete on public.subjects, public.topics, public.materials to authenticated;
create policy subjects_admin on public.subjects for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy topics_admin on public.topics for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy materials_admin on public.materials for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create table public.exams (id uuid primary key default gen_random_uuid(), subject_id uuid not null references public.subjects(id) on delete restrict, title text not null check(char_length(title) between 1 and 200), description text not null default '', published boolean not null default false, created_at timestamptz not null default now());
create table public.exam_questions (id uuid primary key default gen_random_uuid(), exam_id uuid not null references public.exams(id) on delete cascade, position integer not null check(position > 0), question text not null check(char_length(question) between 1 and 2000), options jsonb not null check(jsonb_typeof(options) = 'array' and jsonb_array_length(options) between 2 and 6), unique(exam_id, position));
create table public.exam_answer_keys (question_id uuid primary key references public.exam_questions(id) on delete cascade, correct_index integer not null check(correct_index between 0 and 5));
create table public.exam_attempts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, exam_id uuid references public.exams(id) on delete set null, exam_title text not null, score integer not null check(score >= 0), total integer not null check(total > 0 and score <= total), completed_at timestamptz not null default now());
create table public.chat_messages (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, role text not null check(role in ('user','assistant')), content text not null check(char_length(content) between 1 and 12000), created_at timestamptz not null default now());
create index exam_questions_exam_idx on public.exam_questions(exam_id, position);
create index exam_attempts_user_idx on public.exam_attempts(user_id, completed_at desc);
create index chat_messages_user_idx on public.chat_messages(user_id, created_at);
alter table public.exams enable row level security;
alter table public.exam_questions enable row level security;
alter table public.exam_answer_keys enable row level security;
alter table public.exam_attempts enable row level security;
alter table public.chat_messages enable row level security;
revoke all on public.exams, public.exam_questions, public.exam_answer_keys, public.exam_attempts, public.chat_messages from anon, authenticated;
grant select, insert, update, delete on public.exams, public.exam_questions, public.exam_answer_keys to authenticated;
grant select on public.exam_attempts to authenticated;
grant select, insert, delete on public.chat_messages to authenticated;
create policy exams_read on public.exams for select to authenticated using (published and exists (select 1 from public.subjects s where s.id=subject_id and s.published));
create policy exams_admin on public.exams for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy questions_read on public.exam_questions for select to authenticated using (exists (select 1 from public.exams e where e.id=exam_id and e.published));
create policy questions_admin on public.exam_questions for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy keys_admin on public.exam_answer_keys for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy attempts_read on public.exam_attempts for select to authenticated using (user_id = (select auth.uid()));
create policy chat_read on public.chat_messages for select to authenticated using (user_id = (select auth.uid()));
create policy chat_insert on public.chat_messages for insert to authenticated with check (user_id = (select auth.uid()));
create policy chat_delete on public.chat_messages for delete to authenticated using (user_id = (select auth.uid()));
create function public.submit_exam(p_exam_id uuid, p_answers jsonb) returns public.exam_attempts language plpgsql security definer set search_path = '' as $$
declare v_user uuid := auth.uid(); v_total integer; v_answered integer; v_score integer; v_title text; v_result public.exam_attempts;
begin
 if v_user is null then raise exception 'Autenticação necessária'; end if;
 if jsonb_typeof(p_answers) is distinct from 'object' then raise exception 'Respostas inválidas'; end if;
 select e.title into v_title from public.exams e join public.subjects s on s.id=e.subject_id where e.id=p_exam_id and e.published and s.published;
 if v_title is null then raise exception 'Exame indisponível'; end if;
 select count(*), count(*) filter (where k.question_id is not null and k.correct_index < jsonb_array_length(q.options)) into v_total, v_answered from public.exam_questions q left join public.exam_answer_keys k on k.question_id=q.id where q.exam_id=p_exam_id;
 if v_total = 0 or v_total > 200 or v_total <> v_answered then raise exception 'Exame incompleto'; end if;
 if (select count(*) from jsonb_object_keys(p_answers)) <> v_total then raise exception 'Responde a todas as perguntas'; end if;
 select count(*), count(*) filter (where (p_answers ->> q.id::text)::int = k.correct_index) into v_answered, v_score from public.exam_questions q join public.exam_answer_keys k on k.question_id=q.id where q.exam_id=p_exam_id and (p_answers ->> q.id::text) ~ '^[0-5]$' and (p_answers ->> q.id::text)::int < jsonb_array_length(q.options);
 if v_answered <> v_total then raise exception 'Respostas inválidas'; end if;
 insert into public.exam_attempts(user_id, exam_id, exam_title, score, total) values(v_user, p_exam_id, v_title, v_score, v_total) returning * into v_result;
 return v_result;
end; $$;
revoke all on function public.submit_exam(uuid,jsonb) from public, anon;
grant execute on function public.submit_exam(uuid,jsonb) to authenticated;
